2	#define SYS_CALL_HPP
3	
4	#include "picolib.hpp"
5	
6	#include <fcntl.h>
7	#include <spdlog/spdlog.h>
8	#include <sys/stat.h>
9	#include <sys/time.h>
10	#include <unistd.h>
11	
12	#include <cerrno>
13	#include <cstdint>
14	#include <cstring>
15	
16	#include <algorithm>
17	#include <vector>
18	
19	// NOTE: this header is #include'd inside the SimControl class body
20	// (sim_control.hpp), so the functions here are member functions with implicit
21	// `this`. The helpers below are member functions for the same reason -- they
22	// reach `data_region`, which is a private SimControl member.
23	
24	// Convert a guest VA to a host-pointer into data_region.data. Subtracts
25	// whichever base (region or alias_region) actually contains `va`, so the
26	// index lands at the correct offset whether the region starts at 0x0
27	// (Tier-1, no shared mem), 0x80000000 (Tier-2, --shared-mem-base, narrowed
28	// RAM), or the guest maps DRAM through an alias_region entirely (ax66's
29	// DDR3_MEM_BASE 0x800000000). Without this, a guest VA outside `region`
30	// resolves against the wrong base and can index far outside the owned/mmap
31	// buffer.
32	template<typename T = uint8_t>
33	inline T* guest_va_to_host(uint64_t va)
34	{
35	  const uint64_t off = va - data_region.base_for(va);
36	  return reinterpret_cast<T*>(data_region.data.data() + off);
37	}
38	
39	// Newlib's <sys/_default_fcntl.h> uses BSD-derived O_* values that differ
40	// from the Linux ABI -- e.g. O_CREAT=0x200 in newlib vs 0x40 in Linux,
41	// O_TRUNC=0x400 vs 0x200. Pass-through to host open() with newlib values
42	// would clear O_CREAT/O_EXCL and silently accept O_APPEND, so a fopen("w+")
43	// for a non-existent file fails with ENOENT. Translate flag-by-flag.
44	inline int newlib_to_linux_open_flags(uint64_t newlib_flags)
45	{
46	  constexpr uint64_t NL_RDONLY  = 0;
47	  constexpr uint64_t NL_WRONLY  = 1;
48	  constexpr uint64_t NL_RDWR    = 2;
49	  constexpr uint64_t NL_APPEND  = 0x0008;
50	  constexpr uint64_t NL_CREAT   = 0x0200;
51	  constexpr uint64_t NL_TRUNC   = 0x0400;
52	  constexpr uint64_t NL_EXCL    = 0x0800;
53	  constexpr uint64_t NL_NONBLOCK = 0x4000;
54	  constexpr uint64_t NL_NOCTTY  = 0x8000;
55	
56	  int linux_flags = 0;
57	  switch (newlib_flags & 3) {
58	    case NL_RDONLY: linux_flags |= O_RDONLY; break;
59	    case NL_WRONLY: linux_flags |= O_WRONLY; break;
60	    case NL_RDWR:   linux_flags |= O_RDWR;   break;
61	  }
62	  if (newlib_flags & NL_APPEND)   linux_flags |= O_APPEND;
63	  if (newlib_flags & NL_CREAT)    linux_flags |= O_CREAT;
64	  if (newlib_flags & NL_TRUNC)    linux_flags |= O_TRUNC;
65	  if (newlib_flags & NL_EXCL)     linux_flags |= O_EXCL;
66	  if (newlib_flags & NL_NONBLOCK) linux_flags |= O_NONBLOCK;
67	  if (newlib_flags & NL_NOCTTY)   linux_flags |= O_NOCTTY;
68	  return linux_flags;
69	}
70	
71	uint64_t handle_gettimeofday(uint64_t a0 __attribute__((unused)),
72	                             uint64_t a1 __attribute__((unused)),
73	                             uint64_t a2 __attribute__((unused)),
74	                             uint64_t a3 __attribute__((unused)),
75	                             uint64_t a4 __attribute__((unused)),
76	                             uint64_t a5 __attribute__((unused)),
77	                             uint64_t a6 __attribute__((unused)))
78	{
79	  struct timeval tv;
80	  struct timezone tz;
81	  int ret = gettimeofday(&tv, &tz);
82	  if (ret == -1) {
83	    spdlog::error("sys_call: gettimeofday failed: {}", std::strerror(errno));
84	    return -1;
85	  }
86	
